CREATE TABLE transcription_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), ticket_id uuid NOT NULL REFERENCES tickets(id), attachment_id uuid NOT NULL REFERENCES ticket_attachments(id), status text NOT NULL CHECK(status IN ('QUEUED','RUNNING','SUCCEEDED','RETRY','DEAD_LETTER')), attempts integer NOT NULL DEFAULT 0, transcript text, last_error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE transcription_jobs ENABLE ROW LEVEL SECURITY; CREATE POLICY transcription_jobs_tenant ON transcription_jobs USING(organization_id=app.current_organization_id()) WITH CHECK(organization_id=app.current_organization_id()); GRANT SELECT,INSERT,UPDATE ON transcription_jobs TO jupiter_app;
